<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { publishSocialNote, USER_ID } from '@/api/user'; import { ElMessage } from 'element-plus'
const router=useRouter();const title=ref('');const content=ref('');const coverUrl=ref('');const publishing=ref(false)
async function publish(){if(!title.value.trim()||!content.value.trim())return ElMessage.warning('请填写标题和正文');publishing.value=true;try{await publishSocialNote({userId:USER_ID,title:title.value,content:content.value,coverUrl:coverUrl.value});ElMessage.success('已发布到旅行社区');router.push('/explore')}finally{publishing.value=false}}
</script>
<template><main class="publish"><p class="eyebrow">PUBLISH A TRAVEL NOTE</p><h1>把这段旅程分享出去</h1><p class="sub">可以粘贴 Agent 生成的计划，也可以写下自己的真实经验。</p><input v-model="title" placeholder="标题，例如：杭州 3 日慢旅行"/><input v-model="coverUrl" placeholder="封面图片 URL（可选）"/><textarea v-model="content" rows="16" placeholder="写下路线、预算、避坑经验和你最喜欢的瞬间…"></textarea><div class="actions"><button @click="router.back()">取消</button><button class="primary" :disabled="publishing" @click="publish">{{publishing?'发布中…':'发布笔记'}}</button></div></main></template>
<style scoped>.publish{width:min(760px,calc(100% - 40px));margin:auto;padding:48px 0}.eyebrow{color:var(--sunset);font-size:10px;font-weight:800;letter-spacing:.16em}h1{font:38px 'DM Serif Display';margin:8px 0}.sub{color:var(--ink-2);font-size:14px;margin-bottom:24px}.publish input,.publish textarea{width:100%;border:1px solid var(--line);border-radius:12px;background:var(--card);padding:13px;margin-bottom:12px;font:14px inherit;outline:0}.publish textarea{resize:vertical;line-height:1.7}.actions{display:flex;justify-content:flex-end;gap:10px}.actions button{border:1px solid var(--line);background:var(--card);padding:11px 17px;border-radius:9px;font-weight:800}.actions .primary{background:var(--forest);color:#fff;border-color:var(--forest)}</style>
